code.cpp:
class Solution {
public:
    int largestCombination(vector<int>& candidates) {
        int ans = 0;
        for (int b = 0; b < 24; b++) {
            int cnt = 0;
            for (int c : candidates) {
                if (c & (1 << b)) cnt++;
            }
            ans = max(ans, cnt);
        }
        return ans;
    }
};
